using System.Reflection;
using System.Reflection.Metadata;
using System.Reflection.PortableExecutable;
using PaymentAuthorization.Application;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.ArchitectureTest;

/// <summary>Business layers (Domain, Application) must not touch technical details or outer layers.</summary>
public class LayerDependencyTests
{
    private const string DomainName = "PaymentAuthorization.Domain";
    private const string ApplicationName = "PaymentAuthorization.Application";
    private const string InfrastructureName = "PaymentAuthorization.Infrastructure";

    private static readonly string[] TechnicalNamespaces =
    [
        "System.IO", "System.Net", "System.Data", "System.Diagnostics.Process",
        "System.Security.Cryptography", "System.Reflection", "Microsoft", "Newtonsoft",
    ];

    public static TheoryData<string> BusinessAssemblies => new()
    {
        typeof(Money).Assembly.Location,
        typeof(AuthorizePayment).Assembly.Location,
    };

    [Theory]
    [MemberData(nameof(BusinessAssemblies))]
    public void Business_code_does_not_use_technical_namespaces(string path)
    {
        var violations = ReferencedTypes(path)
            .Where(t => TechnicalNamespaces.Any(n => t.Namespace == n || t.Namespace.StartsWith(n + ".")))
            .Select(t => $"{t.Namespace}.{t.Name}")
            .Distinct().Order().ToList();

        Assert.True(violations.Count == 0, $"{Path.GetFileName(path)} uses technical types: {string.Join(", ", violations)}");
    }

    [Fact]
    public void Domain_does_not_depend_on_outer_layers() =>
        AssertNoAssemblyReference(typeof(Money).Assembly, ApplicationName, InfrastructureName);

    [Fact]
    public void Application_does_not_depend_on_infrastructure() =>
        AssertNoAssemblyReference(typeof(AuthorizePayment).Assembly, InfrastructureName);

    [Fact]
    public void Infrastructure_assembly_is_loaded_for_this_check() =>
        Assert.Equal(InfrastructureName, typeof(FileSystemReceiptStore).Assembly.GetName().Name);

    private static void AssertNoAssemblyReference(Assembly assembly, params string[] forbidden)
    {
        var found = assembly.GetReferencedAssemblies().Select(a => a.Name!).Intersect(forbidden).ToList();
        Assert.True(found.Count == 0, $"{assembly.GetName().Name} references {string.Join(", ", found)}");
    }

    private static IEnumerable<(string Namespace, string Name)> ReferencedTypes(string path)
    {
        using var stream = File.OpenRead(path);
        using var pe = new PEReader(stream);
        var md = pe.GetMetadataReader();
        foreach (var handle in md.TypeReferences)
        {
            var r = md.GetTypeReference(handle);
            yield return (md.GetString(r.Namespace), md.GetString(r.Name));
        }
    }
}
EOF
